using EasyTax.Core.Clients;
using EasyTax.Core.Common;
using Microsoft.EntityFrameworkCore;

namespace EasyTax.Data;

public class EasyTaxDbContext(DbContextOptions<EasyTaxDbContext> options) : DbContext(options)
{
	public DbSet<Client> Clients => Set<Client>();

	protected override void OnModelCreating(ModelBuilder modelBuilder)
	{
		modelBuilder.ApplyConfigurationsFromAssembly(typeof(EasyTaxDbContext).Assembly);

		// Ids are Guid v7 values assigned by the domain, never generated by the database.
		foreach (var entityType in modelBuilder.Model.GetEntityTypes().Where(t => typeof(Entity).IsAssignableFrom(t.ClrType)))
		{
			modelBuilder.Entity(entityType.ClrType).Property(nameof(Entity.Id)).ValueGeneratedNever();
		}
	}
}
